<script setup lang="ts">
import{computed,ref}from'vue';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api}from'../../api/client';import type{CatalogItem,EligibilityResult}from'../../domain/types'
const phone=ref(''),loading=ref(false),error=ref(''),eligibility=ref<EligibilityResult|null>(null),products=ref<CatalogItem[]>([]),selected=ref<CatalogItem|null>(null);const canContinue=computed(()=>eligibility.value?.outcome==='ELIGIBLE'&&!!selected.value)
async function check(){loading.value=true;error.value='';eligibility.value=null;products.value=[];selected.value=null;try{eligibility.value=await api.checkEligibility(phone.value);if(eligibility.value.outcome==='ELIGIBLE'){products.value=await api.getCatalog();selected.value=products.value.find(i=>i.available)||null}}catch{error.value='暂时无法检查号码，请稍后重试。'}finally{loading.value=false}}
function next(){if(!canContinue.value||!selected.value||!eligibility.value)return;uni.setStorageSync('rechargeSelection',{maskedPhone:eligibility.value.maskedPhone,productRef:selected.value.productRef});uni.navigateTo({url:'/pages/recharge/quote'})}
</script>
<template><view class="page"><AppHeader left="返回" @left="uni.navigateBack()"/><view class="content"><view class="progress"><text class="active"/><text/><text/></view><text class="step">第 1 步，共 3 步</text><view class="heading" role="heading" aria-level="1">输入充值号码</view><text class="desc">仅支持孟加拉手机号</text><text class="input-label">手机号码</text><view class="phone-input"><text>+880</text><input v-model="phone" type="number" maxlength="14" placeholder="1712 345 678"/></view><button class="check" :disabled="loading||phone.length<4" @click="check">{{loading?'正在识别…':'识别号码和运营商'}}</button><StatusNotice v-if="eligibility?.outcome==='UNKNOWN'" tone="unknown" title="暂时无法确认该号码">尚未收款，你可以稍后重试或修改号码。</StatusNotice><StatusNotice v-if="error" tone="risk" title="暂时无法检查">{{error}}</StatusNotice><view v-if="eligibility?.outcome==='ELIGIBLE'" class="operator"><text class="operator-logo">✓</text><view><text class="card-title">号码已识别</text><text class="copy">请选择充值金额</text></view></view><view v-if="products.length" class="amount-section"><text class="section-title">选择充值金额</text><view class="amounts"><button v-for="item in products" :key="item.productRef" :class="{selected:selected?.productRef===item.productRef}" @click="selected=item">{{(item.faceValue.minor/100).toFixed(0)}} BDT</button></view></view></view><view class="action"><button class="primary" :disabled="!canContinue" @click="next">下一步</button></view></view></template>
<style src="../../styles/shared.css"></style><style scoped>.progress{display:flex;margin-bottom:20rpx}.progress text{height:8rpx;border-radius:8rpx;background:#d8dee7;flex:1;margin-right:12rpx}.progress text:last-child{margin-right:0}.progress .active{background:var(--brand)}.input-label{display:block;font-size:26rpx;font-weight:700;margin-top:46rpx}.phone-input{display:flex;align-items:center;margin-top:16rpx;padding:28rpx;background:#fff;border:4rpx solid var(--brand);border-radius:28rpx}.phone-input>text{padding-right:24rpx;margin-right:24rpx;border-right:1rpx solid var(--line);color:var(--muted)}.phone-input input{flex:1;font-size:34rpx}.check{display:block;width:100%;margin-top:20rpx;padding:22rpx;color:var(--brand);text-align:center}.operator{display:flex;align-items:center;margin-top:22rpx;padding:26rpx;background:#fff;border-radius:28rpx}.operator-logo{width:72rpx;height:72rpx;line-height:72rpx;margin-right:22rpx;border-radius:22rpx;background:#e7effc;color:var(--brand);text-align:center;font-weight:900}.section-title{display:block;font-size:30rpx;font-weight:800;margin-top:42rpx}.amounts{display:flex;flex-wrap:wrap;margin:14rpx -8rpx 0}.amounts button{width:calc(50% - 16rpx);height:96rpx;margin:8rpx;border:1rpx solid var(--line);border-radius:24rpx;background:#fff;text-align:center;font-weight:700}.amounts .selected{border:4rpx solid var(--brand);background:#edf4ff;color:var(--brand)}</style>
